K = {}
for d in [coal_options, gas_options, renewables_options]:
    for k, v in d.items():
        if k in K:
            raise ValueError(f'Duplicate identifier: {k}')
        K[k] = v
for k in K:
    if 'g' not in K[k] or 'c' not in K[k]:
        raise ValueError(f'Missing g or c for {k}')
D = 200
m = gp.Model('Electricity_Lot_Purchase')
x = m.addVars(K.keys(), lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((K[k]['c'] * x[k] for k in K)), GRB.MINIMIZE)
m.addConstr(gp.quicksum((K[k]['g'] * x[k] for k in K)) >= D, name='demand')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')